{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/kanban-board.json
    Work items in lanes. Each lane has a title, a count and its cards; a card has a title, an optional tag and the person it belongs to. Axes: card (simple, detail: tag and person), cols (2, 3), tone, density. Moving a card between lanes is a port contract.
    Props (p): id, title, lanes, cards, countLabel, card, cols, tone, density, landmarkLabel. -#}
{%- set v_id = ui_def(p['id'], none) -%}
{%- set v_title = ui_def(p['title'], none) -%}
{%- set v_lanes = ui_def(p['lanes'], none) -%}
{%- set v_cards = ui_def(p['cards'], none) -%}
{%- set v_countLabel = ui_def(p['countLabel'], none) -%}
{%- set v_card = ui_def(p['card'], 'detail') -%}
{%- set v_cols = ui_def(p['cols'], '3') -%}
{%- set v_tone = ui_def(p['tone'], 'default') -%}
{%- set v_density = ui_def(p['density'], 'default') -%}
{%- set v_landmarkLabel = ui_def(p['landmarkLabel'], none) -%}
{%- set c_12 -%}
  {%- set c_11 -%}
    {%- for v_lane in ui_l(v_lanes) %}
      {%- set c_10 -%}
        {%- set c_3 -%}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_lane, ['title'])) }}
          {%- endset -%}
          {{ ui_include('ui/title/title.html.j2', {'p': {'As': ui_i(3), 'Size': 'base', 'Weight': 'bold'}, 'children': c_1}) }}
          {%- set c_2 -%}
            {{ ui_text(ui_tpl(v_countLabel, [ui_len(ui_where(v_cards, 'lane', ui_get(v_lane, ['key'])))])) }}
          {%- endset -%}
          {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_2}) }}
        {%- endset -%}
        {{ ui_include('ui/group/group.html.j2', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'between'}, 'children': c_3}) }}
        {%- set c_9 -%}
          {%- for v_c in ui_l(ui_where(v_cards, 'lane', ui_get(v_lane, ['key']))) %}
            {%- set c_8 -%}
              {%- set c_4 -%}
                {{ ui_text(ui_get(v_c, ['title'])) }}
              {%- endset -%}
              {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_4}) }}
              {%- if ui_t(ui_eq(v_card, 'detail')) %}
                {%- set c_7 -%}
                  {%- set c_5 -%}
                    {{ ui_text(ui_get(v_c, ['tag'])) }}
                  {%- endset -%}
                  {{ ui_include('blocks/pill.html.j2', {'p': {'tone': 'blue', 'icon': 'tag'}, 'children': c_5}) }}
                  {%- set c_6 -%}
                    {{ ui_text(ui_get(v_c, ['who'])) }}
                  {%- endset -%}
                  {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_6}) }}
                {%- endset -%}
                {{ ui_include('ui/group/group.html.j2', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'between', 'Class': 'flex-wrap'}, 'children': c_7}) }}
              {%- endif %}
            {%- endset -%}
            {{ ui_include('ui/list/list-item.html.j2', {'p': {'Class': ui_s(ui_cnv(['flex flex-col rounded bg-card inset-ring inset-ring-border', ('gap-2 p-2' if ui_t(ui_eq(v_density, 'compact')) else 'gap-2 p-4')])), 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_8}) }}
          {%- endfor %}
        {%- endset -%}
        {{ ui_include('ui/list/list.html.j2', {'p': {'Class': 'm-0 flex list-none flex-col gap-2 p-0'}, 'children': c_9}) }}
