    {%- endfor %}
  {%- endset -%}
  {{ ui_include('ui/grid/grid.html.j2', {'p': {'Cols': ui_s(('1-2' if ui_t(ui_eq(v_cols, '2')) else '1-3')), 'Class': 'items-start gap-4', 'Attrs': ui_attrs(['data-testid', 'lanes'])}, 'children': c_11}) }}
{%- endset -%}
{{ ui_include('blocks/section-frame.html.j2', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}, 'children': c_12}) }}
